-- Only SELECT policy; no data mutation, no grants/functions changes.
DO $guard$ BEGIN
 IF (SELECT count(*) FROM pg_policy WHERE polrelid='public.drv_missions'::regclass)<>1 OR NOT EXISTS(SELECT 1 FROM pg_policy WHERE polrelid='public.drv_missions'::regclass AND polname='missions read' AND polcmd='r' AND polpermissive AND polroles=ARRAY['authenticated'::regrole::oid] AND md5(pg_get_expr(polqual,polrelid))='73dcff744eb3ec0259e79d48f0dde1ea') THEN RAISE EXCEPTION '0245: policy drift'; END IF;
 IF (SELECT relacl::text FROM pg_class WHERE oid='public.drv_missions'::regclass) IS DISTINCT FROM '{postgres=arwdDxtm/postgres,anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,service_role=arwdDxtm/postgres,sandbox_exec=ar/postgres}' THEN RAISE EXCEPTION '0245: grants drift'; END IF;
 IF md5(pg_get_functiondef('cpn_my_entrepreneur()'::regprocedure)) IS DISTINCT FROM '5107c5489df70245869fc0206b2516e0' OR (SELECT proacl::text FROM pg_proc WHERE oid='cpn_my_entrepreneur()'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION '0245: dependency drift cpn_my_entrepreneur()'; END IF;
 IF md5(pg_get_functiondef('driver_company_active(uuid,uuid)'::regprocedure)) IS DISTINCT FROM 'aff8a32fecc61997bca753060586b215' OR (SELECT proacl::text FROM pg_proc WHERE oid='driver_company_active(uuid,uuid)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION '0245: dependency drift driver_company_active(uuid,uuid)'; END IF;
 IF md5(pg_get_functiondef('driver_identity_current(uuid)'::regprocedure)) IS DISTINCT FROM 'a046ef620c412c47577359667f52b150' OR (SELECT proacl::text FROM pg_proc WHERE oid='driver_identity_current(uuid)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION '0245: dependency drift driver_identity_current(uuid)'; END IF;
 IF md5(pg_get_functiondef('driver_mission_access(uuid,boolean)'::regprocedure)) IS DISTINCT FROM 'e91b36f5f74c6851e440575280af5afa' OR (SELECT proacl::text FROM pg_proc WHERE oid='driver_mission_access(uuid,boolean)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION '0245: dependency drift driver_mission_access(uuid,boolean)'; END IF;
 IF md5(pg_get_functiondef('driver_user_current()'::regprocedure)) IS DISTINCT FROM '53edb5457f53add123151252663d2561' OR (SELECT proacl::text FROM pg_proc WHERE oid='driver_user_current()'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION '0245: dependency drift driver_user_current()'; END IF;
 IF md5(pg_get_functiondef('entcrm_can_admin(uuid)'::regprocedure)) IS DISTINCT FROM '9f95ef48ad456f7f9fddc6a453db9f09' OR (SELECT proacl::text FROM pg_proc WHERE oid='entcrm_can_admin(uuid)'::regprocedure) IS DISTINCT FROM '{=X/postgres,postgres=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION '0245: dependency drift entcrm_can_admin(uuid)'; END IF;
 IF md5(pg_get_functiondef('entcrm_can_read(uuid)'::regprocedure)) IS DISTINCT FROM '5d0444f5cba9f0bb225053e1fb8efcbe' OR (SELECT proacl::text FROM pg_proc WHERE oid='entcrm_can_read(uuid)'::regprocedure) IS DISTINCT FROM '{=X/postgres,postgres=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION '0245: dependency drift entcrm_can_read(uuid)'; END IF;
 IF md5(pg_get_functiondef('fleet_member_role(uuid)'::regprocedure)) IS DISTINCT FROM '41c347ea041497c6e3c0a0642dc65ad4' OR (SELECT proacl::text FROM pg_proc WHERE oid='fleet_member_role(uuid)'::regprocedure) IS DISTINCT FROM '{=X/postgres,postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION '0245: dependency drift fleet_member_role(uuid)'; END IF;
 IF md5(pg_get_functiondef('has_role(uuid,app_role)'::regprocedure)) IS DISTINCT FROM '6e055322eaad390f6c2c3ef45fec6857' OR (SELECT proacl::text FROM pg_proc WHERE oid='has_role(uuid,app_role)'::regprocedure) IS DISTINCT FROM '{=X/postgres,postgres=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION '0245: dependency drift has_role(uuid,app_role)'; END IF;
 IF md5(pg_get_functiondef('jsc_my_driver_ids()'::regprocedure)) IS DISTINCT FROM 'bc85123d4d9c501eb155ef7d1b3dc0ba' OR (SELECT proacl::text FROM pg_proc WHERE oid='jsc_my_driver_ids()'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION '0245: dependency drift jsc_my_driver_ids()'; END IF;
 IF md5(pg_get_functiondef('requisition_access(transport_requests)'::regprocedure)) IS DISTINCT FROM 'abe55241152ee08d3c8a92cd211720fb' OR (SELECT proacl::text FROM pg_proc WHERE oid='requisition_access(transport_requests)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION '0245: dependency drift requisition_access(transport_requests)'; END IF;
END $guard$;
ALTER POLICY "missions read" ON public.drv_missions USING (has_role(auth.uid(), 'admin'::app_role) OR (requisition_id IS NOT NULL AND user_id = auth.uid() AND driver_mission_access(id)) OR (entrepreneur_id = cpn_my_entrepreneur() AND NOT EXISTS (SELECT 1 FROM public.jsc_company_members m WHERE m.user_id = auth.uid() AND m.role = 'chauffeur') AND (company_id IS NULL OR public.fleet_member_role(company_id) IN ('proprietaire','gestionnaire'))));
